local Players=game:GetService("Players");local r=game:GetService("ReplicatedStorage"):WaitForChild("Remotes",10);if not r then return end;local updated=r:WaitForChild("QuestUpdated")::RemoteEvent;local claim=r:WaitForChild("ClaimQuest")::RemoteEvent;local gui=Instance.new("ScreenGui");gui.Name="QuestGui";gui.ResetOnSpawn=false;gui.Enabled=false;gui.Parent=Players.LocalPlayer.PlayerGui;local f=Instance.new("Frame");f.Position=UDim2.fromScale(.72,.2);f.Size=UDim2.fromScale(.26,.5);f.BackgroundColor3=Color3.fromRGB(35,45,60);f.Parent=gui;local list=Instance.new("UIListLayout");list.Parent=f;local close=Instance.new("TextButton");close.Name="Close";close.Size=UDim2.new(1,0,0,36);close.Text="關閉";close.TextScaled=true;close.Parent=f;close.Activated:Connect(function()gui.Enabled=false end);updated.OnClientEvent:Connect(function(d)for _,x in f:GetChildren()do if x:IsA("TextButton")and x~=close then x:Destroy()end end;for _,q in d.quests do local b=Instance.new("TextButton");b.Size=UDim2.new(1,0,0,62);b.Text=string.format("%s %d/%d\n+%d Coins%s",q.name,q.progress,q.target,q.reward,q.claimed and" 已領取"or"");b.TextWrapped=true;b.TextScaled=true;b.Parent=f;b.Activated:Connect(function()claim:FireServer(q.id)end)end end)
